  font-size: 16px;
  line-height: 1.5;
  color: var(--color-text);
  background: var(--color-surface);
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    transition: none !important;
    animation: none !important;
  }
}

